#[test]
fn spec_no_tauri_import_in_src() -> std::io::Result<()> {
    let src_dir = std::path::Path::new("src");
    if src_dir.is_dir() {
        for entry in walkdir(src_dir) {
            let c = std::fs::read_to_string(&entry).unwrap_or_default();
            assert!(!c.contains("tauri::"), "taint: {:?}", entry);
        }
    }
    Ok(())
}

fn walkdir(d: &std::path::Path) -> Vec<std::path::PathBuf> {
    let mut r = Vec::new();
    if let Ok(e) = std::fs::read_dir(d) {
        for entry in e.flatten() {
            let p = entry.path();
            if p.is_dir() && !p.file_name().unwrap().to_str().unwrap().starts_with('.') {
                r.extend(walkdir(&p));
            } else if p.extension().map_or(false, |e| e == "rs") {
                r.push(p);
            }
        }
    }
    r
}
