UT: [Error] C021-postcondition: Bus split rationale — raw_sip overflow has no effect on control bus
  ```rust
  use crate::api::eventbus_receiver::EventBus;
  use crate::api::event_model_payload_bus::{SipEvent, EventMeta, SipEventPayload};
  tokio::runtime::Runtime::new().unwrap().block_on(async {
      let bus = EventBus::new(16, Some(2));
      let mut control_rx = bus.subscribe_control();
      let mut raw_rx = bus.subscribe_raw_sip().unwrap();
      // Flood raw_sip bus past capacity
      for i in 0..10 {
          bus.publish_raw_sip(crate::model::raw_sip_message_spec::RawSipMessage {
              direction: crate::model::raw_sip_message_spec::SipMessageDirection::Incoming,
              transport: crate::model::raw_sip_message_spec::TransportKind::Udp,
              start_line: String::new(), headers: vec![], body: None, text: String::new(),
              content_length: 0, remote_addr: None, local_addr: None,
          });
      }
      // raw_rx must have lagged; control_rx must NOT be affected
      let raw_result = raw_rx.try_recv();
      assert!(matches!(raw_result, Err(tokio::sync::broadcast::error::TryRecvError::Lagged(_))));
      // Control bus still works
      bus.publish(SipEvent { meta: EventMeta { event_id: 0, timestamp: 0, account_id: None, call_id: None, direction: None, headers: None, status_code: None, reason_phrase: None, logical_context: std::collections::BTreeMap::new() }, payload: SipEventPayload::ClientShutdown });
      assert!(control_rx.try_recv().is_ok());
  });
  ```

UT: [Invariant] C021-invariant: Events are observation-only — broadcast does not implement reliable delivery
  ```rust
  use crate::api::eventbus_receiver::EventBus;
  use crate::api::event_model_payload_bus::{SipEvent, EventMeta, SipEventPayload};
  tokio::runtime::Runtime::new().unwrap().block_on(async {
      let bus = EventBus::new(2, None);
      let mut rx = bus.subscribe_control();
      let event = SipEvent { meta: EventMeta { event_id: 0, timestamp: 0, account_id: None, call_id: None, direction: None, headers: None, status_code: None, reason_phrase: None, logical_context: std::collections::BTreeMap::new() }, payload: SipEventPayload::ClientShutdown };
      bus.publish(event.clone());
      bus.publish(event.clone());
      bus.publish(event.clone()); // 3rd send: capacity=2, rx hasn't read → lagged
      let result = rx.try_recv();
      assert!(result.is_ok() || matches!(&result, Err(tokio::sync::broadcast::error::TryRecvError::Lagged(_))));
  });
  ```

